package cz.playlingo.core

/**
 * Nápověda jako postup od začátku (od 0.97, `help()` v MainActivity): kapitoly `hc<číslo>_…` podle
 * zvolené televize a konzole, výběr „Nápověda pro“ (`help_for`), a drobné texty z téže verze
 * (náhled `pv_stale`, převzetí Remote Play `ls_other_device`, aktuální aplikace v televizi).
 * HELP_S = čeština a slovenština, HELP_X = ostatní jazyky.
 */
internal val HELP_S: Map<String, Pair<String, String>> = mapOf(
    "help_for" to ("Instalace pro" to "Inštalácia pre"),
    "hc1" to ("1. Instalace PlayLinga" to "1. Inštalácia PlayLinga"),
    "hc1_android" to ("PlayLingo patří do Android TV nebo boxu s Androidem, který je zapojený v televizi. Soubor PlayLingo.apk se nahraje aplikací Downloader (adresa je na stránce s návodem), nebo z flash disku správcem souborů. Další verze už se nabídnou samy na Domů." to "PlayLingo patrí do Android TV alebo boxu s Androidom, ktorý je zapojený v televízore. Súbor PlayLingo.apk sa nahrá aplikáciou Downloader (adresa je na stránke s návodom), alebo z flash disku správcom súborov. Ďalšie verzie sa už ponúknu samy na Domov."),
    "hc1_reader" to ("Televize LG a Samsung si obraz hry samy nepřečtou. PlayLingo proto běží v telefonu s Androidem (nebo v boxu): čte obraz z konzole, překládá a hotové titulky posílá do aplikace PlayLingo v televizi. Do telefonu se stáhne a nainstaluje PlayLingo.apk (odkaz je na stránce s návodem)." to "Televízory LG a Samsung si obraz hry samy neprečítajú. PlayLingo preto beží v telefóne s Androidom (alebo v boxe): číta obraz z konzoly, prekladá a hotové titulky posiela do aplikácie PlayLingo v televízore. Do telefónu sa stiahne a nainštaluje PlayLingo.apk (odkaz je na stránke s návodom)."),
    "hc2" to ("2. Příprava konzole" to "2. Príprava konzoly"),
    "hc2_ps" to ("Na PS5 je potřeba založit druhého uživatele s jiným účtem PlayStation (zdarma) – 🔵 účet pro PlayLingo. Aplikace se připojuje jím – kdyby se připojila 🟢 herním účtem, konzole by při hraní vypínala ovladač. Pod 🔵 druhým uživatelem zapnout Nastavení → Systém → Remote Play → Povolit Remote Play. Hraje se pak normálně pod 🟢 herním účtem." to "Na PS5 treba založiť druhého používateľa s iným účtom PlayStation (zadarmo) – 🔵 účet pre PlayLingo. Aplikácia sa pripája ním – keby sa pripojila 🟢 herným účtom, konzola by pri hraní vypínala ovládač. Pod 🔵 druhým používateľom zapnúť Nastavenia → Systém → Remote Play → Povoliť Remote Play. Hrá sa potom normálne pod 🟢 herným účtom."),
    "hc2_xbox" to ("Na Xboxu zapnout Nastavení → Zařízení a připojení → Vzdálené funkce a režim napájení nechat „Spánek“ (ne úsporný). V PlayLingu pak na stránce Xbox přihlásit účet Microsoft kódem na microsoft.com/link a vybrat Xbox." to "Na Xboxe zapnúť Nastavenia → Zariadenia a pripojenia → Vzdialené funkcie a režim napájania nechať „Spánok“ (nie úsporný). V PlayLingu potom na stránke Xbox prihlásiť účet Microsoft kódom na microsoft.com/link a vybrať Xbox."),
    "hc3" to ("3. Televize" to "3. Televízor"),
    "hc3_android" to ("Pruh s překladem kreslí PlayLingo přes obraz hry. Povoluje se v nastavení televize: Usnadnění → PlayLingo → Zapnout (případně „Zobrazení přes jiné aplikace“). Když televize tu obrazovku nemá, jde to povolit z počítače:" to "Pruh s prekladom kreslí PlayLingo cez obraz hry. Povoľuje sa v nastaveniach televízora: Zjednodušenie ovládania → PlayLingo → Zapnúť (prípadne „Zobrazenie cez iné aplikácie“). Keď televízor tú obrazovku nemá, dá sa to povoliť z počítača:"),
    "hc3_lg" to ("Do televize LG patří aplikace PlayLingo (obrazovka s hrou a pruhem). Nahraje se z tohoto zařízení přes vývojářský režim LG – pomocník provede krok za krokem a hotové kroky odškrtá sám. Vývojářský režim po čase vyprší, Domů včas upozorní. Tohle zařízení musí být ve stejné domácí síti jako televize. Prodloužit vývojářský režim jde jen v televizi v aplikaci Developer Mode (Extend) – PlayLingo ho samo neprodlužuje. Když vyprší, PlayLingo z televize zmizí a nahraje se znovu. Jde to i z počítače nástrojem LG ares (postup na github.com/adusa89/PlayLingo, složka webos)." to "Do televízora LG patrí aplikácia PlayLingo (obrazovka s hrou a pruhom). Nahrá sa z tohto zariadenia cez vývojársky režim LG – pomocník prevedie krok za krokom a hotové kroky odškrtne sám. Vývojársky režim po čase vyprší, Domov včas upozorní. Toto zariadenie musí byť v rovnakej domácej sieti ako televízor. Predĺžiť vývojársky režim ide len v televízore v aplikácii Developer Mode (Extend) – PlayLingo ho samo nepredlžuje. Keď vyprší, PlayLingo z televízora zmizne a nahrá sa znova. Dá sa to aj z počítača nástrojom LG ares (postup na github.com/adusa89/PlayLingo, priečinok webos)."),
    "hc4" to ("4. Jazyk a kvalita překladu" to "4. Jazyk a kvalita prekladu"),
    "hc4_text" to ("Jazyk překladu se vybírá v Titulkách. Pod ním je „Překládat z“ – jazyk titulků ve hře (výchozí angličtina). Jazykový balíček se stáhne jednou (asi 30 MB) a pak se překládá offline a zdarma. Lepší překlad přes DeepL (vlastní klíč zdarma) se nastaví v Titulkách → Kvalita překladu: na televizi stačí naskenovat jeden čtvereček – stránka v telefonu provede registrací na DeepL, zkopírováním i vložením klíče." to "Jazyk prekladu sa vyberá v Titulkoch. Pod ním je „Prekladať z“ – jazyk titulkov v hre (predvolene angličtina). Jazykový balík sa stiahne raz (asi 30 MB) a potom sa prekladá offline a zadarmo. Lepší preklad cez DeepL (vlastný kľúč zadarmo) sa nastaví v Titulkoch → Kvalita prekladu: na televízore stačí naskenovať jeden štvorček – stránka v telefóne prevedie registráciou na DeepL, skopírovaním aj vložením kľúča."),
    "hc5" to ("5. Spárování konzole" to "5. Spárovanie konzoly"),
    "hc5_text" to ("Jednou a podle průvodce na stránce Konzole: zvolit 🔵 druhý účet (pro PlayLingo), přihlásit ho telefonem (čtvereček) a na PS5 pod stejným uživatelem zapnout Remote Play a vyvolat osmimístné číslo. Když ho vyvolá jiný uživatel, PS5 hlásí CE‑110032‑7. Pak se na PS5 přepnout zpět na 🟢 herní účet." to "Raz a podľa sprievodcu na stránke Konzola: zvoliť 🔵 druhý účet (pre PlayLingo), prihlásiť ho telefónom (štvorček) a na PS5 pod rovnakým používateľom zapnúť Remote Play a vyvolať osemmiestne číslo. Keď ho vyvolá iný používateľ, PS5 hlási CE‑110032‑7. Potom sa na PS5 prepnúť späť na 🟢 herný účet."),
    "hc6" to ("6. Hraní" to "6. Hranie"),
    "hc6_android" to ("Na Domů spustit překlad, počkat na „obraz přichází“ a přepnout televizi na HDMI s konzolí. Ve hře musí být zapnuté anglické titulky. Vzhled a poloha pruhu se mění v Titulkách." to "Na Domov spustiť preklad, počkať na „obraz prichádza“ a prepnúť televízor na HDMI s konzolou. V hre musia byť zapnuté anglické titulky. Vzhľad a poloha pruhu sa mení v Titulkoch."),
    "hc6_tv" to ("V PlayLingu (telefon) spustit překlad. V televizi otevřít aplikaci PlayLingo a vybrat HDMI s konzolí – telefon najde sama. Ve hře musí být zapnuté anglické titulky. Vzhled pruhu se mění v Titulkách v telefonu, nebo při hře tlačítkem OK na ovladači televize. Telefon může ležet, displej smí zhasnout." to "V PlayLingu (telefón) spustiť preklad. V televízore otvoriť aplikáciu PlayLingo a vybrať HDMI s konzolou – telefón nájde sama. V hre musia byť zapnuté anglické titulky. Vzhľad pruhu sa mení v Titulkoch v telefóne, alebo pri hre tlačidlom OK na ovládači televízora. Telefón môže ležať, displej smie zhasnúť."),
    "hc7" to ("7. Když něco nejde" to "7. Keď niečo nejde"),
    "hc7_qr" to ("Stránka ze čtverečku se v telefonu neotevře: telefon musí být na stejné Wi-Fi (ne na mobilních datech)." to "Stránka zo štvorčeka sa v telefóne neotvorí: telefón musí byť na rovnakej Wi-Fi (nie na mobilných dátach)."),
    "hc7_ps5" to ("Konzole se nepřipojí: zkontrolovat Remote Play pod druhým uživatelem a že konzole i toto zařízení jsou ve stejné síti." to "Konzola sa nepripojí: skontrolovať Remote Play pod druhým používateľom a že konzola aj toto zariadenie sú v rovnakej sieti."),
    "hc7_net" to ("Spojení vypadává: na Wi-Fi 2,4 GHz vysílají ve stejném pásmu i ovladače konzole. Pomůže připojit konzoli k routeru kabelem, nebo přepnout toto zařízení na Wi-Fi 5 GHz." to "Spojenie vypadáva: na Wi-Fi 2,4 GHz vysielajú v rovnakom pásme aj ovládače konzoly. Pomôže pripojiť konzolu k routeru káblom, alebo prepnúť toto zariadenie na Wi-Fi 5 GHz."),
    "hc7_battery" to ("Telefon: spojení vypadává se zhasnutým displejem – v ⚙ Nastavení → Obecné zapnout „Povolit běh na pozadí“ (šetření baterie PlayLingo uspává)." to "Telefón: spojenie vypadáva so zhasnutým displejom – v ⚙ Nastaveniach → Všeobecné zapnúť „Povoliť beh na pozadí“ (šetrenie batérie PlayLingo uspáva)."),
    "hc7_other" to ("Na PS5 naskakuje „ovladač odpojen / účet připojen“: se stejným druhým účtem se připojuje jiné zařízení (třeba aplikace PS Remote Play). Druhý účet má sloužit jen PlayLingu." to "Na PS5 naskakuje „ovládač odpojený / účet pripojený“: s rovnakým druhým účtom sa pripája iné zariadenie (napríklad aplikácia PS Remote Play). Druhý účet má slúžiť len PlayLingu."),
    "hc7_read" to ("Titulky nenaskakují: zapnout ⚙ Nastavení → Experimentální → Ladění a hlášení → Diagnostický režim – ukáže, co aplikace čte. Pomůže i hlášení chyby poslané do telefonu." to "Titulky nenaskakujú: zapnúť ⚙ Nastavenia → Experimentálne → Ladenie a hlásenia → Diagnostický režim – ukáže, čo aplikácia číta. Pomôže aj hlásenie chyby poslané do telefónu."),
    "hc8" to ("8. Volby v Nastavení" to "8. Voľby v Nastaveniach"),
    "help_page" to ("Stránka s návodem" to "Stránka s návodom"),
    "ls_other_device" to ("Remote Play na PS5 teď používá jiné zařízení se stejným účtem (třeba aplikace PS Remote Play). PlayLingo se připojí, až ho uvolní." to "Remote Play na PS5 teraz používa iné zariadenie s rovnakým účtom (napríklad aplikácia PS Remote Play). PlayLingo sa pripojí, keď ho uvoľní."),
    "pv_stale" to ("Náhled je poslední přijatý snímek – teď obraz nepřichází:" to "Náhľad je posledná prijatá snímka – teraz obraz neprichádza:"),
    "lg_launch" to ("Spustit PlayLingo v TV" to "Spustiť PlayLingo v TV"),
    "tv_current" to ("PlayLingo v TV · verze %s" to "PlayLingo v TV · verzia %s"),
    "lg_pass_other" to ("Zadat Passphrase znovu" to "Zadať Passphrase znova"),
)

internal val HELP_X: Map<Lang, Map<String, String>> = mapOf(
    Lang.EN to mapOf(
        "help_for" to "Setup for",
        "hc1" to "1. Installing PlayLingo",
        "hc1_android" to "PlayLingo goes on the Android TV or Android box connected to the TV. Install PlayLingo.apk with the Downloader app (the address is on the guide page) or from a USB stick with a file manager. Later versions are offered automatically on Home.",
        "hc1_reader" to "LG and Samsung TVs can’t read the game picture themselves. So PlayLingo runs on an Android phone (or a box): it reads the picture from the console, translates and sends the finished subtitles to the PlayLingo app on the TV. Download PlayLingo.apk to the phone and install it (the link is on the guide page).",
        "hc2" to "2. Preparing the console",
        "hc2_ps" to "On the PS5 add a second user with another PlayStation account (free) – the 🔵 account for PlayLingo. The app connects with it – if it used your 🟢 gaming account, the console would turn off your controller while you play. Under the 🔵 second user turn on Settings → System → Remote Play → Enable Remote Play. You then play as usual under your own 🟢 gaming account.",
        "hc2_xbox" to "On the Xbox turn on Settings → Devices & connections → Remote features and keep the power mode at “Sleep” (not energy saving). Then on the Xbox page in PlayLingo sign in with a Microsoft account using the code at microsoft.com/link and choose your Xbox.",
        "hc3" to "3. TV",
        "hc3_android" to "PlayLingo draws the translation bar over the game picture. Allow it in the TV settings: Accessibility → PlayLingo → On (or “Display over other apps”). If the TV doesn’t have that screen, it can be allowed from a computer:",
        "hc3_lg" to "The PlayLingo app goes on the LG TV (a screen with the game and the bar). It is installed from this device via LG Developer Mode – the helper guides you step by step and ticks off finished steps by itself. Developer Mode expires after a while; Home warns you in time. This device must be in the same home network as the TV. Developer Mode can only be extended on the TV in the Developer Mode app (Extend) – PlayLingo never extends it. When it expires, PlayLingo disappears from the TV and is installed again. It can also be installed from a computer with the LG tool ares (see github.com/adusa89/PlayLingo, folder webos).",
        "hc4" to "4. Language and translation quality",
        "hc4_text" to "Choose the translation language in Subtitles. Below it, “Translate from” is the language of the game’s subtitles (English by default). The language pack downloads once (about 30 MB), then translation is offline and free. Better translation with DeepL (your own free key) is set up in Subtitles → Translation quality: on the TV just scan one QR code – the page on your phone walks you through DeepL sign-up, copying and pasting the key.",
        "hc5" to "5. Pairing the console",
        "hc5_text" to "Once, following the guide on the Console page: choose the 🔵 second account (for PlayLingo), sign it in with your phone (QR code), then on the PS5, as the same user, turn on Remote Play and get the eight-digit number. If another user gets the number, the PS5 shows CE‑110032‑7. Then switch the PS5 back to your 🟢 gaming account.",
        "hc6" to "6. Playing",
        "hc6_android" to "Start the translation on Home, wait for “the picture is arriving” and switch the TV to the console’s HDMI. Keep English subtitles on in the game. Change the bar’s look and position in Subtitles.",
        "hc6_tv" to "Start the translation in PlayLingo (phone). On the TV open the PlayLingo app and choose the console’s HDMI – it finds the phone by itself. Keep English subtitles on in the game. Change the bar’s look in Subtitles on the phone, or while playing with OK on the TV remote. Leave the phone lying; its screen may turn off.",
        "hc7" to "7. When something doesn’t work",
        "hc7_qr" to "The page from the QR code won’t open on the phone: the phone must be on the same Wi-Fi (not mobile data).",
        "hc7_ps5" to "The console won’t connect: check Remote Play under the second user and that the console and this device are on the same network.",
        "hc7_net" to "The connection drops: on 2.4 GHz Wi-Fi the console’s controllers use the same band. Connect the console to the router with a cable, or switch this device to 5 GHz Wi-Fi.",
        "hc7_battery" to "Phone: the connection drops with the screen off – in ⚙ Settings → General turn on “Allow background use” (battery saving puts PlayLingo to sleep).",
        "hc7_other" to "The PS5 keeps showing “controller disconnected / account connected”: another device connects with the same second account (e.g. the PS Remote Play app). The second account should be used only by PlayLingo.",
        "hc7_read" to "No subtitles appear: turn on ⚙ Settings → Experimental → Debugging and reports → Diagnostic mode to see what the app reads. A bug report sent to your phone helps too.",
        "hc8" to "8. Options in Settings",
        "help_page" to "Guide page",
        "ls_other_device" to "Remote Play on the PS5 is now used by another device with the same account (e.g. the PS Remote Play app). PlayLingo connects once it’s free.",
        "pv_stale" to "The preview is the last received frame – the picture isn’t arriving now:",
        "lg_launch" to "Start PlayLingo on the TV",
        "tv_current" to "PlayLingo is on the TV (version %s)",
        "lg_pass_other" to "Enter the Passphrase again",
    ),
    Lang.PL to mapOf(
        "help_for" to "Instalacja dla",
        "hc1" to "1. Instalacja PlayLingo",
        "hc1_android" to "PlayLingo instaluje się na Android TV lub przystawce z Androidem podłączonej do telewizora. PlayLingo.apk wgrywa się aplikacją Downloader (adres jest na stronie z instrukcją) albo z pendrive’a menedżerem plików. Kolejne wersje pojawią się same na Start.",
        "hc1_reader" to "Telewizory LG i Samsung same nie odczytają obrazu gry. Dlatego PlayLingo działa w telefonie z Androidem (lub w przystawce): czyta obraz z konsoli, tłumaczy i wysyła gotowe napisy do aplikacji PlayLingo w telewizorze. Na telefon trzeba pobrać i zainstalować PlayLingo.apk (link jest na stronie z instrukcją).",
        "hc2" to "2. Przygotowanie konsoli",
        "hc2_ps" to "Na PS5 dodać 🔵 drugiego użytkownika z innym kontem PlayStation (za darmo). Aplikacja łączy się nim – gdyby użyła 🟢 konta do gry, konsola wyłączałaby kontroler podczas gry. U 🔵 drugiego użytkownika włączyć Ustawienia → System → Remote Play → Włącz Remote Play. Gra się potem normalnie na 🟢 koncie do gry.",
        "hc2_xbox" to "Na Xboxie włączyć Ustawienia → Urządzenia i połączenia → Funkcje zdalne, a tryb zasilania zostawić na „Uśpienie” (nie oszczędzanie energii). Potem w PlayLingo na stronie Xbox zalogować konto Microsoft kodem na microsoft.com/link i wybrać Xboxa.",
        "hc3" to "3. Telewizor",
        "hc3_android" to "PlayLingo rysuje pasek z tłumaczeniem nad obrazem gry. Trzeba na to zezwolić w ustawieniach telewizora: Ułatwienia dostępu → PlayLingo → Włącz (ewentualnie „Wyświetlanie nad innymi aplikacjami”). Jeśli telewizor nie ma tego ekranu, da się to zrobić z komputera:",
        "hc3_lg" to "Na telewizor LG trafia aplikacja PlayLingo (ekran z grą i paskiem). Wgrywa się ją z tego urządzenia przez tryb deweloperski LG – pomocnik prowadzi krok po kroku i sam odhacza gotowe kroki. Tryb deweloperski po czasie wygasa; Start ostrzeże na czas. To urządzenie musi być w tej samej sieci domowej co telewizor. Tryb deweloperski można przedłużyć tylko na telewizorze w aplikacji Developer Mode (Extend) – PlayLingo nigdy go nie przedłuża. Po wygaśnięciu PlayLingo zniknie z telewizora i trzeba je wgrać ponownie. Da się to też zrobić z komputera narzędziem LG ares (opis na github.com/adusa89/PlayLingo, folder webos).",
        "hc4" to "4. Język i jakość tłumaczenia",
        "hc4_text" to "Język tłumaczenia wybiera się w Napisach. Pod nim „Tłumacz z” to język napisów w grze (domyślnie angielski). Pakiet językowy pobiera się raz (ok. 30 MB), potem tłumaczenie działa offline i za darmo. Lepsze tłumaczenie przez DeepL (własny darmowy klucz) ustawia się w Napisy → Jakość tłumaczenia: na telewizorze wystarczy zeskanować jeden kod QR – strona w telefonie przeprowadzi przez rejestrację w DeepL, skopiowanie i wklejenie klucza.",
        "hc5" to "5. Parowanie konsoli",
        "hc5_text" to "Raz, według przewodnika na stronie Konsola: wybrać 🔵 drugie konto (dla PlayLingo), zalogować je telefonem (kod QR), a na PS5 na tym samym użytkowniku włączyć Granie zdalne i wywołać ośmiocyfrowy numer. Jeśli wywoła go inny użytkownik, PS5 pokaże CE‑110032‑7. Potem przełączyć PS5 z powrotem na 🟢 konto do gry.",
        "hc6" to "6. Granie",
        "hc6_android" to "Na Start uruchomić tłumaczenie, poczekać na „obraz dociera” i przełączyć telewizor na HDMI konsoli. W grze muszą być włączone angielskie napisy. Wygląd i położenie paska zmienia się w Napisach.",
        "hc6_tv" to "Uruchomić tłumaczenie w PlayLingo (telefon). W telewizorze otworzyć aplikację PlayLingo i wybrać HDMI konsoli – sama znajdzie telefon. W grze muszą być włączone angielskie napisy. Wygląd paska zmienia się w Napisach w telefonie albo w trakcie gry przyciskiem OK na pilocie telewizora. Telefon może leżeć, ekran może zgasnąć.",
        "hc7" to "7. Gdy coś nie działa",
        "hc7_qr" to "Strona z kodu QR nie otwiera się w telefonie: telefon musi być w tej samej sieci Wi-Fi (nie na danych komórkowych).",
        "hc7_ps5" to "Konsola się nie łączy: sprawdzić Remote Play u drugiego użytkownika i czy konsola i to urządzenie są w tej samej sieci.",
        "hc7_net" to "Połączenie się zrywa: w Wi-Fi 2,4 GHz w tym samym paśmie działają kontrolery konsoli. Pomoże podłączenie konsoli do routera kablem albo przełączenie tego urządzenia na Wi-Fi 5 GHz.",
        "hc7_battery" to "Telefon: połączenie zrywa się przy wygaszonym ekranie – w ⚙ Ustawienia → Ogólne włączyć „Zezwól na działanie w tle” (oszczędzanie baterii usypia PlayLingo).",
        "hc7_other" to "Na PS5 ciągle wyskakuje „kontroler odłączony / konto połączone”: z tym samym drugim kontem łączy się inne urządzenie (np. aplikacja PS Remote Play). Drugie konto ma służyć tylko PlayLingo.",
        "hc7_read" to "Napisy się nie pojawiają: włączyć ⚙ Ustawienia → Eksperymentalne → Debugowanie i zgłoszenia → Tryb diagnostyczny – pokaże, co aplikacja czyta. Pomoże też zgłoszenie błędu wysłane do telefonu.",
        "hc8" to "8. Opcje w Ustawieniach",
        "help_page" to "Strona z instrukcją",
        "ls_other_device" to "Remote Play na PS5 używa teraz inne urządzenie z tym samym kontem (np. aplikacja PS Remote Play). PlayLingo połączy się, gdy je zwolni.",
        "pv_stale" to "Podgląd to ostatnia odebrana klatka – obraz teraz nie dociera:",
        "lg_launch" to "Uruchomić PlayLingo w telewizorze",
        "tv_current" to "PlayLingo jest w telewizorze (wersja %s)",
        "lg_pass_other" to "Wpisać Passphrase ponownie",
    ),
    Lang.DE to mapOf(
        "help_for" to "Einrichtung für",
        "hc1" to "1. PlayLingo installieren",
        "hc1_android" to "PlayLingo gehört auf das Android TV oder die Android-Box am Fernseher. PlayLingo.apk wird mit der App Downloader (die Adresse steht auf der Anleitungsseite) oder per USB-Stick mit einem Dateimanager installiert. Neue Versionen werden danach auf Start angeboten.",
        "hc1_reader" to "LG- und Samsung-Fernseher können das Spielbild nicht selbst lesen. PlayLingo läuft deshalb auf einem Android-Telefon (oder einer Box): Es liest das Bild der Konsole, übersetzt und schickt die fertigen Untertitel an die PlayLingo-App auf dem Fernseher. PlayLingo.apk aufs Telefon laden und installieren (Link auf der Anleitungsseite).",
        "hc2" to "2. Konsole vorbereiten",
        "hc2_ps" to "Auf der PS5 einen 🔵 zweiten Benutzer mit einem anderen PlayStation-Konto anlegen (kostenlos). Die App verbindet sich damit – mit dem 🟢 Spielkonto würde die Konsole beim Spielen den Controller trennen. Beim 🔵 zweiten Benutzer Einstellungen → System → Remote Play → Remote Play aktivieren einschalten. Gespielt wird dann wie gewohnt mit dem 🟢 Spielkonto.",
        "hc2_xbox" to "Auf der Xbox Einstellungen → Geräte & Verbindungen → Remotefunktionen einschalten und den Energiemodus auf „Ruhezustand“ lassen (nicht Energiesparen). Dann in PlayLingo auf der Seite Xbox ein Microsoft-Konto mit dem Code auf microsoft.com/link anmelden und die Xbox wählen.",
        "hc3" to "3. Fernseher",
        "hc3_android" to "PlayLingo zeichnet den Übersetzungsbalken über das Spielbild. Das wird in den Fernseheinstellungen erlaubt: Bedienungshilfen → PlayLingo → Ein (oder „Über anderen Apps einblenden“). Fehlt diese Seite, geht es auch vom Computer:",
        "hc3_lg" to "Auf den LG-Fernseher kommt die App PlayLingo (Bild mit Spiel und Balken). Sie wird von diesem Gerät über den LG-Entwicklermodus installiert – der Helfer führt Schritt für Schritt und hakt erledigte Schritte selbst ab. Der Entwicklermodus läuft nach einiger Zeit ab; Start warnt rechtzeitig. Dieses Gerät muss im selben Heimnetz sein wie der Fernseher. Verlängern lässt sich der Entwicklermodus nur am Fernseher in der App Developer Mode (Extend) – PlayLingo verlängert ihn nie. Läuft er ab, verschwindet PlayLingo vom Fernseher und wird neu installiert. Es geht auch vom Computer mit dem LG-Werkzeug ares (Anleitung auf github.com/adusa89/PlayLingo, Ordner webos).",
        "hc4" to "4. Sprache und Übersetzungsqualität",
        "hc4_text" to "Die Übersetzungssprache wird unter Untertitel gewählt. Darunter ist „Übersetzen aus“ die Sprache der Untertitel im Spiel (standardmäßig Englisch). Das Sprachpaket wird einmal geladen (ca. 30 MB), danach wird offline und kostenlos übersetzt. Bessere Übersetzung mit DeepL (eigener kostenloser Schlüssel) wird unter Untertitel → Übersetzungsqualität eingerichtet: am Fernseher genügt ein QR-Code – die Seite auf dem Handy führt durch Registrierung bei DeepL, Kopieren und Einfügen des Schlüssels.",
        "hc5" to "5. Konsole koppeln",
        "hc5_text" to "Einmal, mit der Anleitung auf der Seite Konsole: 🔵 zweites Konto (für PlayLingo) wählen, mit dem Handy anmelden (QR-Code), dann auf der PS5 unter demselben Benutzer Remote Play aktivieren und die achtstellige Zahl anzeigen lassen. Zeigt sie ein anderer Benutzer an, meldet die PS5 CE‑110032‑7. Danach auf der PS5 zurück zum 🟢 Spielkonto wechseln.",
        "hc6" to "6. Spielen",
        "hc6_android" to "Auf Start die Übersetzung starten, auf „Bild kommt an“ warten und den Fernseher auf den HDMI-Eingang der Konsole schalten. Englische Untertitel im Spiel einschalten. Aussehen und Position des Balkens werden unter Untertitel geändert.",
        "hc6_tv" to "Die Übersetzung in PlayLingo (Telefon) starten. Auf dem Fernseher die App PlayLingo öffnen und den HDMI-Eingang der Konsole wählen – sie findet das Telefon selbst. Englische Untertitel im Spiel einschalten. Das Aussehen des Balkens wird unter Untertitel im Telefon oder beim Spielen mit OK auf der Fernbedienung geändert. Das Telefon kann liegen bleiben, das Display darf ausgehen.",
        "hc7" to "7. Wenn etwas nicht geht",
        "hc7_qr" to "Die Seite vom QR-Code öffnet sich nicht: Das Telefon muss im selben WLAN sein (nicht mobile Daten).",
        "hc7_ps5" to "Die Konsole verbindet sich nicht: Remote Play beim zweiten Benutzer prüfen und ob Konsole und dieses Gerät im selben Netz sind.",
        "hc7_net" to "Die Verbindung bricht ab: Im 2,4-GHz-WLAN funken auch die Controller der Konsole. Abhilfe: die Konsole per Kabel an den Router anschließen oder dieses Gerät auf 5-GHz-WLAN schalten.",
        "hc7_battery" to "Telefon: Die Verbindung bricht bei ausgeschaltetem Display ab – unter ⚙ Einstellungen → Allgemein „Hintergrundnutzung erlauben“ einschalten (der Energiesparmodus legt PlayLingo schlafen).",
        "hc7_other" to "Auf der PS5 erscheint immer wieder „Controller getrennt / Konto verbunden“: Ein anderes Gerät verbindet sich mit demselben zweiten Konto (z. B. die App PS Remote Play). Das zweite Konto soll nur PlayLingo dienen.",
        "hc7_read" to "Es erscheinen keine Untertitel: ⚙ Einstellungen → Experimentell → Fehlersuche und Berichte → Diagnosemodus einschalten – er zeigt, was die App liest. Auch ein ans Telefon gesendeter Fehlerbericht hilft.",
        "hc8" to "8. Optionen in den Einstellungen",
        "help_page" to "Anleitungsseite",
        "ls_other_device" to "Remote Play auf der PS5 nutzt gerade ein anderes Gerät mit demselben Konto (z. B. die App PS Remote Play). PlayLingo verbindet sich, sobald es frei ist.",
        "pv_stale" to "Die Vorschau ist das zuletzt empfangene Bild – gerade kommt kein Bild an:",
        "lg_launch" to "PlayLingo auf dem Fernseher starten",
        "tv_current" to "PlayLingo ist auf dem Fernseher (Version %s)",
        "lg_pass_other" to "Passphrase erneut eingeben",
    ),
    Lang.HU to mapOf(
        "help_for" to "Telepítés ehhez",
        "hc1" to "1. A PlayLingo telepítése",
        "hc1_android" to "A PlayLingo a tévére kötött Android TV-re vagy androidos boxra kerül. A PlayLingo.apk a Downloader alkalmazással (a cím az útmutató oldalán van) vagy pendrive-ról fájlkezelővel telepíthető. A későbbi verziókat a Kezdőlap magától felajánlja.",
        "hc1_reader" to "Az LG és Samsung tévék maguk nem tudják olvasni a játék képét. Ezért a PlayLingo androidos telefonon (vagy boxon) fut: olvassa a konzol képét, fordít, és a kész feliratokat elküldi a tévén futó PlayLingo alkalmazásnak. A PlayLingo.apk-t le kell tölteni a telefonra és telepíteni (a link az útmutató oldalán van).",
        "hc2" to "2. A konzol előkészítése",
        "hc2_ps" to "A PS5-ön létre kell hozni egy 🔵 második felhasználót másik PlayStation-fiókkal (ingyenes). Az alkalmazás ezzel csatlakozik – ha a 🟢 játékfiókkal tenné, a konzol játék közben lekapcsolná a kontrollert. A 🔵 második felhasználónál be kell kapcsolni: Beállítások → Rendszer → Remote Play → Remote Play engedélyezése. Utána a játék a 🟢 játékfiókkal megy, mint eddig.",
        "hc2_xbox" to "Az Xboxon be kell kapcsolni: Beállítások → Eszközök és kapcsolatok → Távoli funkciók, az energiamód maradjon „Alvó” (ne energiatakarékos). Utána a PlayLingo Xbox oldalán bejelentkezés Microsoft-fiókkal a microsoft.com/link kóddal, majd az Xbox kiválasztása.",
        "hc3" to "3. Tévé",
        "hc3_android" to "A PlayLingo a fordítási sávot a játék képe fölé rajzolja. Engedélyezni kell a tévé beállításaiban: Kisegítő lehetőségek → PlayLingo → Be (vagy „Megjelenítés más alkalmazások felett”). Ha a tévén nincs ilyen oldal, számítógépről is engedélyezhető:",
        "hc3_lg" to "Az LG tévére a PlayLingo alkalmazás kerül (képernyő a játékkal és a sávval). Erről az eszközről települ az LG fejlesztői módon át – a segéd lépésről lépésre vezet, és a kész lépéseket maga pipálja ki. A fejlesztői mód idővel lejár; a Kezdőlap időben szól. Ennek az eszköznek ugyanazon az otthoni hálózaton kell lennie, mint a tévének. A fejlesztői módot csak a tévén, a Developer Mode alkalmazásban lehet meghosszabbítani (Extend) – a PlayLingo soha nem hosszabbítja meg. Ha lejár, a PlayLingo eltűnik a tévéről, és újra kell telepíteni. Számítógépről is telepíthető az LG ares eszközével (leírás: github.com/adusa89/PlayLingo, webos mappa).",
        "hc4" to "4. Nyelv és fordítási minőség",
        "hc4_text" to "A fordítás nyelve a Feliratokban választható ki. Alatta a „Forrásnyelv” a játék feliratainak nyelve (alapból angol). A nyelvi csomag egyszer töltődik le (kb. 30 MB), utána a fordítás offline és ingyenes. Jobb fordítás DeepL-lel (saját ingyenes kulcs): Feliratok → Fordítás minősége. A tévén elég egy QR-kódot beolvasni – a telefonos oldal végigvezet a DeepL-regisztráción, a kulcs másolásán és beillesztésén.",
        "hc5" to "5. A konzol párosítása",
        "hc5_text" to "Egyszer, a Konzol oldal útmutatója szerint: a 🔵 második fiók kiválasztása (a PlayLingóhoz), bejelentkezés vele telefonon (QR-kód), majd a PS5-ön ugyanazzal a felhasználóval a Távoli játék bekapcsolása és a nyolcjegyű szám lekérése. Ha más felhasználó kéri le, a PS5 CE‑110032‑7 hibát jelez. Utána a PS5-ön vissza kell váltani a 🟢 játékfiókra.",
        "hc6" to "6. Játék",
        "hc6_android" to "A Kezdőlapon el kell indítani a fordítást, megvárni, hogy „a kép érkezik”, és a tévét a konzol HDMI-bemenetére kapcsolni. A játékban legyen bekapcsolva az angol felirat. A sáv kinézete és helye a Feliratokban állítható.",
        "hc6_tv" to "A fordítást a PlayLingóban (telefon) kell elindítani. A tévén meg kell nyitni a PlayLingo alkalmazást, és a konzol HDMI-bemenetét választani – a telefont maga megtalálja. A játékban legyen bekapcsolva az angol felirat. A sáv kinézete a telefonon a Feliratokban, vagy játék közben a tévé távirányítójának OK gombjával módosítható. A telefon maradhat fekve, a kijelzője kikapcsolhat.",
        "hc7" to "7. Ha valami nem működik",
        "hc7_qr" to "A QR-kód oldala nem nyílik meg a telefonon: a telefonnak ugyanazon a Wi-Fi-n kell lennie (nem mobiladaton).",
        "hc7_ps5" to "A konzol nem csatlakozik: érdemes ellenőrizni a Remote Playt a második felhasználónál, és hogy a konzol és ez az eszköz ugyanazon a hálózaton van-e.",
        "hc7_net" to "A kapcsolat megszakad: 2,4 GHz-es Wi-Fi-n ugyanabban a sávban működnek a konzol kontrollerei is. Segít, ha a konzol kábellel csatlakozik a routerhez, vagy ez az eszköz 5 GHz-es Wi-Fi-re vált.",
        "hc7_battery" to "Telefon: a kapcsolat kikapcsolt kijelzőnél megszakad – a ⚙ Beállítások → Általános alatt be kell kapcsolni a „Háttérben futás engedélyezése” lehetőséget (az akkumulátorkímélés elaltatja a PlayLingót).",
        "hc7_other" to "A PS5-ön folyton „kontroller leválasztva / fiók csatlakoztatva” jelenik meg: ugyanazzal a második fiókkal másik eszköz csatlakozik (pl. a PS Remote Play alkalmazás). A második fiók csak a PlayLingót szolgálja.",
        "hc7_read" to "Nem jelennek meg feliratok: a ⚙ Beállítások → Kísérleti → Hibakeresés és jelentések → Diagnosztikai mód megmutatja, mit olvas az alkalmazás. Segít a telefonra küldött hibajelentés is.",
        "hc8" to "8. A Beállítások lehetőségei",
        "help_page" to "Útmutató oldal",
        "ls_other_device" to "A PS5 Remote Playét most egy másik eszköz használja ugyanazzal a fiókkal (pl. a PS Remote Play alkalmazás). A PlayLingo csatlakozik, ha felszabadul.",
        "pv_stale" to "Az előnézet az utoljára kapott kép – most nem érkezik kép:",
        "lg_launch" to "PlayLingo indítása a tévén",
        "tv_current" to "A PlayLingo a tévén van (%s verzió)",
        "lg_pass_other" to "Passphrase újbóli megadása",
    ),
    Lang.UK to mapOf(
        "help_for" to "Встановлення для",
        "hc1" to "1. Встановлення PlayLingo",
        "hc1_android" to "PlayLingo встановлюється на Android TV або Android-приставку, підключену до телевізора. Завантажити PlayLingo.apk можна застосунком Downloader (адреса на сторінці з інструкцією) або з флешки файловим менеджером. Наступні версії запропонуються самі на Головній.",
        "hc1_reader" to "Телевізори LG і Samsung не можуть самі читати зображення гри. Тому PlayLingo працює на Android-телефоні (або приставці): читає зображення з консолі, перекладає й надсилає готові субтитри в застосунок PlayLingo на телевізорі. PlayLingo.apk треба завантажити в телефон і встановити (посилання на сторінці з інструкцією).",
        "hc2" to "2. Підготовка консолі",
        "hc2_ps" to "На PS5 додати 🔵 другого користувача з іншим обліковим записом PlayStation (безкоштовно). Застосунок підключається через нього – якби він використав 🟢 ігровий запис, консоль вимикала б контролер під час гри. У 🔵 другого користувача увімкнути Налаштування → Система → Remote Play → Увімкнути Remote Play. Грати потім як завжди під 🟢 ігровим записом.",
        "hc2_xbox" to "На Xbox увімкнути Налаштування → Пристрої та підключення → Віддалені функції, а режим живлення залишити «Сон» (не енергозбереження). Потім у PlayLingo на сторінці Xbox увійти з обліковим записом Microsoft кодом на microsoft.com/link і вибрати Xbox.",
        "hc3" to "3. Телевізор",
        "hc3_android" to "PlayLingo малює смугу з перекладом поверх зображення гри. Це дозволяється в налаштуваннях телевізора: Спеціальні можливості → PlayLingo → Увімкнути (або «Показ поверх інших застосунків»). Якщо такого екрана немає, це можна дозволити з комп’ютера:",
        "hc3_lg" to "На телевізор LG ставиться застосунок PlayLingo (екран з грою та смугою). Він встановлюється з цього пристрою через режим розробника LG – помічник проведе крок за кроком і сам позначить виконані кроки. Режим розробника з часом спливає; Головна вчасно попередить. Цей пристрій має бути в тій самій домашній мережі, що й телевізор. Подовжити режим розробника можна лише на телевізорі в застосунку Developer Mode (Extend) – PlayLingo його ніколи не подовжує. Коли він спливе, PlayLingo зникне з телевізора і його треба встановити знову. Встановити можна й з комп’ютера інструментом LG ares (опис на github.com/adusa89/PlayLingo, тека webos).",
        "hc4" to "4. Мова та якість перекладу",
        "hc4_text" to "Мова перекладу вибирається в Субтитрах. Під ним «Перекладати з» – мова субтитрів у грі (типово англійська). Мовний пакет завантажується один раз (близько 30 МБ), далі переклад офлайн і безкоштовно. Кращий переклад через DeepL (власний безкоштовний ключ) налаштовується в Субтитри → Якість перекладу: на телевізорі досить відсканувати один QR-код – сторінка в телефоні проведе через реєстрацію в DeepL, копіювання й вставлення ключа.",
        "hc5" to "5. З’єднання консолі",
        "hc5_text" to "Один раз, за інструкцією на сторінці Консоль: вибрати 🔵 другий запис (для PlayLingo), увійти ним через телефон (QR-код), а на PS5 під тим самим користувачем увімкнути дистанційну гру й викликати восьмизначне число. Якщо його викличе інший користувач, PS5 покаже CE‑110032‑7. Потім на PS5 перемкнутися назад на 🟢 ігровий запис.",
        "hc6" to "6. Гра",
        "hc6_android" to "На Головній запустити переклад, дочекатися «зображення надходить» і перемкнути телевізор на HDMI консолі. У грі мають бути увімкнені англійські субтитри. Вигляд і положення смуги змінюються в Субтитрах.",
        "hc6_tv" to "Запустити переклад у PlayLingo (телефон). На телевізорі відкрити застосунок PlayLingo і вибрати HDMI консолі – телефон він знайде сам. У грі мають бути увімкнені англійські субтитри. Вигляд смуги змінюється в Субтитрах на телефоні або під час гри кнопкою OK на пульті телевізора. Телефон може лежати, екран може згаснути.",
        "hc7" to "7. Коли щось не працює",
        "hc7_qr" to "Сторінка з QR-коду не відкривається в телефоні: телефон має бути в тій самій Wi-Fi (не на мобільних даних).",
        "hc7_ps5" to "Консоль не підключається: перевірити Remote Play у другого користувача і чи консоль та цей пристрій в одній мережі.",
        "hc7_net" to "З’єднання обривається: у Wi-Fi 2,4 ГГц у тому ж діапазоні працюють контролери консолі. Допоможе під’єднати консоль до роутера кабелем або перемкнути цей пристрій на Wi-Fi 5 ГГц.",
        "hc7_battery" to "Телефон: з’єднання обривається при вимкненому екрані – у ⚙ Налаштування → Загальні увімкнути «Дозволити роботу у фоні» (економія батареї приспає PlayLingo).",
        "hc7_other" to "На PS5 постійно з’являється «контролер відключено / запис підключено»: з тим самим другим записом підключається інший пристрій (напр. застосунок PS Remote Play). Другий запис має служити лише PlayLingo.",
        "hc7_read" to "Субтитри не з’являються: увімкнути ⚙ Налаштування → Експериментальне → Налагодження та звіти → Діагностичний режим – він покаже, що читає застосунок. Допоможе й звіт про помилку, надісланий у телефон.",
        "hc8" to "8. Параметри в Налаштуваннях",
        "help_page" to "Сторінка з інструкцією",
        "ls_other_device" to "Remote Play на PS5 зараз використовує інший пристрій з тим самим записом (напр. застосунок PS Remote Play). PlayLingo підключиться, коли його звільнять.",
        "pv_stale" to "Попередній перегляд – останній отриманий кадр, зараз зображення не надходить:",
        "lg_launch" to "Запустити PlayLingo на телевізорі",
        "tv_current" to "PlayLingo є на телевізорі (версія %s)",
        "lg_pass_other" to "Ввести Passphrase знову",
    ),
    Lang.ES to mapOf(
        "help_for" to "Instalación para",
        "hc1" to "1. Instalar PlayLingo",
        "hc1_android" to "PlayLingo se instala en el Android TV o la caja Android conectada al televisor. PlayLingo.apk se instala con la app Downloader (la dirección está en la página de la guía) o desde un USB con un gestor de archivos. Las versiones nuevas se ofrecen solas en Inicio.",
        "hc1_reader" to "Los televisores LG y Samsung no pueden leer la imagen del juego por sí mismos. Por eso PlayLingo funciona en un teléfono Android (o una caja): lee la imagen de la consola, traduce y envía los subtítulos terminados a la app PlayLingo del televisor. Descargar PlayLingo.apk en el teléfono e instalarlo (el enlace está en la página de la guía).",
        "hc2" to "2. Preparar la consola",
        "hc2_ps" to "En la PS5, añadir un 🔵 segundo usuario con otra cuenta de PlayStation (gratis). La app se conecta con él: si usara la 🟢 cuenta de juego, la consola apagaría el mando durante la partida. Con el 🔵 segundo usuario, activar Ajustes → Sistema → Juego remoto → Habilitar juego remoto. Luego se juega como siempre con la 🟢 cuenta de juego.",
        "hc2_xbox" to "En la Xbox, activar Configuración → Dispositivos y conexiones → Funciones remotas y dejar el modo de energía en «Suspensión» (no ahorro de energía). Luego, en la página Xbox de PlayLingo, iniciar sesión con una cuenta Microsoft con el código en microsoft.com/link y elegir la Xbox.",
        "hc3" to "3. Televisor",
        "hc3_android" to "PlayLingo dibuja la barra de traducción sobre la imagen del juego. Se permite en los ajustes del televisor: Accesibilidad → PlayLingo → Activar (o «Mostrar sobre otras apps»). Si el televisor no tiene esa pantalla, se puede permitir desde un ordenador:",
        "hc3_lg" to "En el televisor LG va la app PlayLingo (pantalla con el juego y la barra). Se instala desde este dispositivo mediante el modo desarrollador de LG: el asistente guía paso a paso y marca solo los pasos hechos. El modo desarrollador caduca con el tiempo; Inicio avisa a tiempo. Este dispositivo debe estar en la misma red doméstica que el televisor. El modo desarrollador solo se amplía en el televisor, en la app Developer Mode (Extend); PlayLingo nunca lo amplía. Si caduca, PlayLingo desaparece del televisor y hay que instalarlo de nuevo. También se puede instalar desde un ordenador con la herramienta de LG ares (instrucciones en github.com/adusa89/PlayLingo, carpeta webos).",
        "hc4" to "4. Idioma y calidad de la traducción",
        "hc4_text" to "El idioma de la traducción se elige en Subtítulos. Debajo, «Traducir desde» es el idioma de los subtítulos del juego (inglés por defecto). El paquete de idioma se descarga una vez (unos 30 MB) y luego la traducción es sin conexión y gratis. Una traducción mejor con DeepL (clave propia gratuita) se configura en Subtítulos → Calidad de la traducción: en la tele basta con escanear un código QR: la página en el móvil guía por el registro en DeepL y por copiar y pegar la clave.",
        "hc5" to "5. Vincular la consola",
        "hc5_text" to "Una vez, siguiendo la guía de la página Consola: elegir la 🔵 segunda cuenta (para PlayLingo), iniciar sesión con el móvil (código QR) y en la PS5, con ese mismo usuario, activar Uso a distancia y pedir el número de ocho cifras. Si lo pide otro usuario, la PS5 muestra CE‑110032‑7. Después, volver en la PS5 a la 🟢 cuenta de juego.",
        "hc6" to "6. Jugar",
        "hc6_android" to "En Inicio, iniciar la traducción, esperar a «la imagen llega» y cambiar el televisor al HDMI de la consola. Los subtítulos en inglés del juego deben estar activados. El aspecto y la posición de la barra se cambian en Subtítulos.",
        "hc6_tv" to "Iniciar la traducción en PlayLingo (teléfono). En el televisor, abrir la app PlayLingo y elegir el HDMI de la consola: encuentra el teléfono sola. Los subtítulos en inglés del juego deben estar activados. El aspecto de la barra se cambia en Subtítulos en el teléfono o, durante la partida, con OK en el mando del televisor. El teléfono puede quedarse quieto; la pantalla puede apagarse.",
        "hc7" to "7. Cuando algo no funciona",
        "hc7_qr" to "La página del código QR no se abre en el teléfono: el teléfono debe estar en la misma Wi-Fi (no con datos móviles).",
        "hc7_ps5" to "La consola no se conecta: comprobar el Juego remoto del segundo usuario y que la consola y este dispositivo estén en la misma red.",
        "hc7_net" to "La conexión se corta: en Wi-Fi de 2,4 GHz los mandos de la consola usan la misma banda. Ayuda conectar la consola al router por cable o pasar este dispositivo a Wi-Fi de 5 GHz.",
        "hc7_battery" to "Teléfono: la conexión se corta con la pantalla apagada; en ⚙ Ajustes → General activar «Permitir uso en segundo plano» (el ahorro de batería suspende PlayLingo).",
        "hc7_other" to "En la PS5 aparece una y otra vez «mando desconectado / cuenta conectada»: otro dispositivo se conecta con la misma segunda cuenta (p. ej. la app PS Remote Play). La segunda cuenta debe ser solo para PlayLingo.",
        "hc7_read" to "No aparecen subtítulos: activar ⚙ Ajustes → Experimental → Depuración e informes → Modo de diagnóstico para ver qué lee la app. También ayuda un informe de error enviado al teléfono.",
        "hc8" to "8. Opciones de Ajustes",
        "help_page" to "Página de la guía",
        "ls_other_device" to "El Juego remoto de la PS5 lo usa ahora otro dispositivo con la misma cuenta (p. ej. la app PS Remote Play). PlayLingo se conectará cuando quede libre.",
        "pv_stale" to "La vista previa es el último fotograma recibido; ahora no llega imagen:",
        "lg_launch" to "Iniciar PlayLingo en el televisor",
        "tv_current" to "PlayLingo está en el televisor (versión %s)",
        "lg_pass_other" to "Introducir de nuevo la Passphrase",
    ),
    Lang.FR to mapOf(
        "help_for" to "Installation pour",
        "hc1" to "1. Installer PlayLingo",
        "hc1_android" to "PlayLingo s’installe sur l’Android TV ou le boîtier Android branché au téléviseur. PlayLingo.apk s’installe avec l’appli Downloader (l’adresse est sur la page du guide) ou depuis une clé USB avec un gestionnaire de fichiers. Les versions suivantes sont proposées toutes seules sur Accueil.",
        "hc1_reader" to "Les téléviseurs LG et Samsung ne savent pas lire eux-mêmes l’image du jeu. PlayLingo tourne donc sur un téléphone Android (ou un boîtier) : il lit l’image de la console, traduit et envoie les sous-titres prêts à l’appli PlayLingo du téléviseur. Télécharger PlayLingo.apk sur le téléphone et l’installer (le lien est sur la page du guide).",
        "hc2" to "2. Préparer la console",
        "hc2_ps" to "Sur la PS5, ajouter un 🔵 deuxième utilisateur avec un autre compte PlayStation (gratuit). L’appli se connecte avec lui : avec le 🟢 compte de jeu, la console déconnecterait la manette pendant la partie. Pour le 🔵 deuxième utilisateur, activer Paramètres → Système → Remote Play → Activer Remote Play. On joue ensuite normalement avec le 🟢 compte de jeu.",
        "hc2_xbox" to "Sur la Xbox, activer Paramètres → Appareils et connexions → Fonctionnalités à distance et garder le mode d’alimentation sur « Veille » (pas économie d’énergie). Puis, sur la page Xbox de PlayLingo, connecter un compte Microsoft avec le code sur microsoft.com/link et choisir la Xbox.",
        "hc3" to "3. Téléviseur",
        "hc3_android" to "PlayLingo dessine le bandeau de traduction par-dessus l’image du jeu. À autoriser dans les réglages du téléviseur : Accessibilité → PlayLingo → Activer (ou « Afficher par-dessus les autres applis »). Si le téléviseur n’a pas cet écran, on peut l’autoriser depuis un ordinateur :",
        "hc3_lg" to "Sur le téléviseur LG va l’appli PlayLingo (écran avec le jeu et le bandeau). Elle s’installe depuis cet appareil via le mode développeur LG : l’assistant guide pas à pas et coche tout seul les étapes faites. Le mode développeur expire au bout d’un moment ; Accueil prévient à temps. Cet appareil doit être sur le même réseau domestique que le téléviseur. Le mode développeur ne se prolonge que sur le téléviseur, dans l’app Developer Mode (Extend) ; PlayLingo ne le prolonge jamais. S’il expire, PlayLingo disparaît du téléviseur et doit être réinstallé. L’installation est aussi possible depuis un ordinateur avec l’outil LG ares (voir github.com/adusa89/PlayLingo, dossier webos).",
        "hc4" to "4. Langue et qualité de traduction",
        "hc4_text" to "La langue de traduction se choisit dans Sous-titres. Juste en dessous, « Traduire depuis » est la langue des sous-titres du jeu (anglais par défaut). Le pack de langue se télécharge une fois (environ 30 Mo), ensuite la traduction est hors ligne et gratuite. Une meilleure traduction avec DeepL (clé personnelle gratuite) se règle dans Sous-titres → Qualité de la traduction : sur la télé, un seul QR code à scanner – la page sur le téléphone guide pour l’inscription chez DeepL, la copie et le collage de la clé.",
        "hc5" to "5. Associer la console",
        "hc5_text" to "Une fois, avec le guide de la page Console : choisir le 🔵 second compte (pour PlayLingo), le connecter avec le téléphone (QR code), puis sur la PS5, sous le même utilisateur, activer la Lecture à distance et demander le nombre à huit chiffres. Si un autre utilisateur le demande, la PS5 affiche CE‑110032‑7. Ensuite, repasser la PS5 sur le 🟢 compte de jeu.",
        "hc6" to "6. Jouer",
        "hc6_android" to "Sur Accueil, lancer la traduction, attendre « l’image arrive » et passer le téléviseur sur l’HDMI de la console. Les sous-titres anglais doivent être activés dans le jeu. L’apparence et la position du bandeau se changent dans Sous-titres.",
        "hc6_tv" to "Lancer la traduction dans PlayLingo (téléphone). Sur le téléviseur, ouvrir l’appli PlayLingo et choisir l’HDMI de la console : elle trouve le téléphone toute seule. Les sous-titres anglais doivent être activés dans le jeu. L’apparence du bandeau se change dans Sous-titres sur le téléphone, ou en jouant avec OK sur la télécommande du téléviseur. Le téléphone peut rester posé, l’écran peut s’éteindre.",
        "hc7" to "7. Quand quelque chose ne marche pas",
        "hc7_qr" to "La page du QR code ne s’ouvre pas sur le téléphone : le téléphone doit être sur le même Wi-Fi (pas en données mobiles).",
        "hc7_ps5" to "La console ne se connecte pas : vérifier Remote Play pour le deuxième utilisateur et que la console et cet appareil sont sur le même réseau.",
        "hc7_net" to "La connexion décroche : en Wi-Fi 2,4 GHz, les manettes de la console utilisent la même bande. Solution : relier la console au routeur par câble ou passer cet appareil en Wi-Fi 5 GHz.",
        "hc7_battery" to "Téléphone : la connexion décroche écran éteint – dans ⚙ Réglages → Général activer « Autoriser en arrière-plan » (l’économie de batterie met PlayLingo en veille).",
        "hc7_other" to "La PS5 affiche sans cesse « manette déconnectée / compte connecté » : un autre appareil se connecte avec le même deuxième compte (par ex. l’appli PS Remote Play). Le deuxième compte doit servir uniquement à PlayLingo.",
        "hc7_read" to "Aucun sous-titre n’apparaît : activer ⚙ Réglages → Expérimental → Débogage et rapports → Mode diagnostic pour voir ce que lit l’appli. Un rapport d’erreur envoyé au téléphone aide aussi.",
        "hc8" to "8. Options des Réglages",
        "help_page" to "Page du guide",
        "ls_other_device" to "Remote Play sur la PS5 est utilisé maintenant par un autre appareil avec le même compte (par ex. l’appli PS Remote Play). PlayLingo se connectera dès qu’il sera libre.",
        "pv_stale" to "L’aperçu est la dernière image reçue – l’image n’arrive pas en ce moment :",
        "lg_launch" to "Lancer PlayLingo sur le téléviseur",
        "tv_current" to "PlayLingo est sur le téléviseur (version %s)",
        "lg_pass_other" to "Saisir à nouveau la Passphrase",
    ),
    Lang.IT to mapOf(
        "help_for" to "Installazione per",
        "hc1" to "1. Installare PlayLingo",
        "hc1_android" to "PlayLingo va sull’Android TV o sul box Android collegato al televisore. PlayLingo.apk si installa con l’app Downloader (l’indirizzo è nella pagina della guida) o da una chiavetta USB con un file manager. Le versioni successive vengono proposte da sole in Home.",
        "hc1_reader" to "I televisori LG e Samsung non sanno leggere da soli l’immagine del gioco. Per questo PlayLingo funziona su un telefono Android (o un box): legge l’immagine della console, traduce e invia i sottotitoli pronti all’app PlayLingo sul televisore. Scaricare PlayLingo.apk sul telefono e installarlo (il link è nella pagina della guida).",
        "hc2" to "2. Preparare la console",
        "hc2_ps" to "Sulla PS5 aggiungere un 🔵 secondo utente con un altro account PlayStation (gratis). L’app si collega con quello: con l’🟢 account di gioco la console scollegherebbe il controller durante il gioco. Per il 🔵 secondo utente attivare Impostazioni → Sistema → Riproduzione remota → Abilita Riproduzione remota. Poi si gioca come sempre con l’🟢 account di gioco.",
        "hc2_xbox" to "Sulla Xbox attivare Impostazioni → Dispositivi e connessioni → Funzionalità remote e lasciare la modalità di alimentazione su «Sospensione» (non risparmio energia). Poi nella pagina Xbox di PlayLingo accedere con un account Microsoft con il codice su microsoft.com/link e scegliere la Xbox.",
        "hc3" to "3. Televisore",
        "hc3_android" to "PlayLingo disegna la barra di traduzione sopra l’immagine del gioco. Va consentito nelle impostazioni del televisore: Accessibilità → PlayLingo → Attiva (oppure «Mostra sopra altre app»). Se il televisore non ha quella schermata, si può consentire da un computer:",
        "hc3_lg" to "Sul televisore LG va l’app PlayLingo (schermata con il gioco e la barra). Si installa da questo dispositivo tramite la modalità sviluppatore LG: l’assistente guida passo passo e spunta da solo i passi fatti. La modalità sviluppatore scade dopo un po’; Home avvisa in tempo. Questo dispositivo deve essere nella stessa rete di casa del televisore. La modalità sviluppatore si estende solo sul televisore, nell’app Developer Mode (Extend): PlayLingo non la estende mai. Quando scade, PlayLingo sparisce dal televisore e va installato di nuovo. Si può installare anche da computer con lo strumento LG ares (istruzioni su github.com/adusa89/PlayLingo, cartella webos).",
        "hc4" to "4. Lingua e qualità della traduzione",
        "hc4_text" to "La lingua di traduzione si sceglie in Sottotitoli. Sotto, «Traduci da» è la lingua dei sottotitoli del gioco (inglese per impostazione predefinita). Il pacchetto lingua si scarica una volta (circa 30 MB), poi la traduzione è offline e gratuita. Una traduzione migliore con DeepL (chiave personale gratuita) si imposta in Sottotitoli → Qualità della traduzione: sulla TV basta scansionare un codice QR – la pagina sul telefono guida nella registrazione a DeepL, nella copia e nell’incolla della chiave.",
        "hc5" to "5. Associare la console",
        "hc5_text" to "Una volta, seguendo la guida nella pagina Console: scegliere il 🔵 secondo account (per PlayLingo), accedere con il telefono (codice QR) e sulla PS5, con lo stesso utente, attivare Riproduzione remota e richiedere il numero di otto cifre. Se lo richiede un altro utente, la PS5 mostra CE‑110032‑7. Poi sulla PS5 tornare all’🟢 account di gioco.",
        "hc6" to "6. Giocare",
        "hc6_android" to "In Home avviare la traduzione, aspettare «l’immagine arriva» e passare il televisore all’HDMI della console. I sottotitoli in inglese nel gioco devono essere attivi. Aspetto e posizione della barra si cambiano in Sottotitoli.",
        "hc6_tv" to "Avviare la traduzione in PlayLingo (telefono). Sul televisore aprire l’app PlayLingo e scegliere l’HDMI della console: trova il telefono da sola. I sottotitoli in inglese nel gioco devono essere attivi. L’aspetto della barra si cambia in Sottotitoli sul telefono o, giocando, con OK sul telecomando del televisore. Il telefono può restare appoggiato, lo schermo può spegnersi.",
        "hc7" to "7. Quando qualcosa non va",
        "hc7_qr" to "La pagina del codice QR non si apre sul telefono: il telefono deve essere sulla stessa Wi-Fi (non sui dati mobili).",
        "hc7_ps5" to "La console non si collega: controllare la Riproduzione remota del secondo utente e che console e questo dispositivo siano sulla stessa rete.",
        "hc7_net" to "La connessione cade: sulla Wi-Fi a 2,4 GHz i controller della console usano la stessa banda. Aiuta collegare la console al router via cavo o passare questo dispositivo alla Wi-Fi a 5 GHz.",
        "hc7_battery" to "Telefono: la connessione cade a schermo spento – in ⚙ Impostazioni → Generali attivare «Consenti uso in background» (il risparmio batteria sospende PlayLingo).",
        "hc7_other" to "Sulla PS5 compare di continuo «controller scollegato / account collegato»: un altro dispositivo si collega con lo stesso secondo account (ad es. l’app PS Remote Play). Il secondo account deve servire solo a PlayLingo.",
        "hc7_read" to "Non compaiono sottotitoli: attivare ⚙ Impostazioni → Sperimentale → Debug e segnalazioni → Modalità diagnostica per vedere cosa legge l’app. Aiuta anche una segnalazione inviata al telefono.",
        "hc8" to "8. Opzioni delle Impostazioni",
        "help_page" to "Pagina della guida",
        "ls_other_device" to "La Riproduzione remota della PS5 ora è usata da un altro dispositivo con lo stesso account (ad es. l’app PS Remote Play). PlayLingo si collegherà quando sarà libera.",
        "pv_stale" to "L’anteprima è l’ultimo fotogramma ricevuto – ora l’immagine non arriva:",
        "lg_launch" to "Avviare PlayLingo sul televisore",
        "tv_current" to "PlayLingo è sul televisore (versione %s)",
        "lg_pass_other" to "Inserire di nuovo la Passphrase",
    ),
)
